function renderLab(){let current=lab.components.find(x=>x.id===lab.selected),audit=analyzeLab(),java=generatedJava();app.innerHTML=`<div class="lab-header"><div><span class="eyebrow">EXPERIMENTE · JAVA SWING</span><h1 class="page-title">Laboratório de interfaces</h1><p>Adicione componentes, monte uma janela e leve o código para testar no VS Code. A prévia representa a estrutura; a interface real aparece ao executar Java.</p></div></div><div class="lab-layout"><section class="lab-panel"><h2>1. Monte sua tela</h2><div class="field"><label for="labTitle">Título da janela</label><input id="labTitle" value="${esc(lab.title)}" maxlength="80"></div><p class="panel-note">Comece com um exemplo ou monte do zero.</p><div class="template-buttons"><button class="chip" data-template="login">Login</button><button class="chip" data-template="cadastro">Cadastro</button><button class="chip" data-template="tarefas">Tarefas</button></div><div class="topic-heading" style="margin:23px 0 11px">Adicionar componente</div><div class="lab-palette">${labGroups.map(([name,items],i)=>`<details class="lab-group" ${i===labActiveGroup?'open':''}><summary>${name}<span>${items.length} componentes</span></summary><div class="palette-grid">${items.map(k=>`<button class="palette-btn" data-add="${k}">${icon(iconMap[k])}${labels[k]}</button>`).join('')}</div></details>`).join('')}</div><p class="panel-note">Componentes são adicionados de cima para baixo. Toque num item para editar.</p></section><section class="lab-panel"><h2>2. Veja sua janela</h2><div class="mock-window"><div class="window-bar"><span class="window-dot"></span><span class="window-dot"></span><span class="window-dot"></span><span class="window-title">${esc(lab.title||'Minha tela')}</span></div><div class="window-content">${lab.components.length?lab.components.map(c=>`<div data-select="${c.id}" style="display:contents">${previewComponent(c)}</div>`).join(''):`<div class="empty-canvas">${icon('window')}Sua tela começa aqui.<br>Adicione um componente à esquerda.</div>`}</div></div><div class="component-list">${lab.components.map((c,i)=>`<div class="component-item ${c.id===lab.selected?'active':''}"><button class="tiny-btn" aria-label="Selecionar ${esc(labels[c.type])}" data-select="${c.id}">${icon('grid')}</button><span>${esc(labels[c.type])}: ${esc(c.text)}</span><button class="tiny-btn" aria-label="Subir" data-move="${c.id}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button class="tiny-btn" aria-label="Descer" data-move="${c.id}" data-dir="1" ${i===lab.components.length-1?'disabled':''}>↓</button></div>`).join('')}</div></section><section class="lab-panel"><h2>3. Ajuste e revise</h2>${current?`<div class="field"><label for="propText">Texto · ${esc(labels[current.type])}</label><input id="propText" value="${esc(current.text)}" maxlength="120"></div><button class="button button-danger" data-action="remove">Remover componente</button>`:`<p class="panel-note">Selecione um componente para editar seu texto ou remover.</p>`}<div class="topic-heading">O que sua tela já faz bem</div><ul class="audit-list">${audit.good.length?audit.good.map(x=>`<li>${esc(x)}</li>`).join(''):'<li>Adicione componentes para receber uma análise.</li>'}</ul><div class="topic-heading">Sugestões para melhorar</div><ul class="audit-list">${audit.suggest.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section></div><div class="lab-result"><section class="lab-panel"><h2>Código Java gerado</h2><p class="panel-note">Salve como MinhaTela.java. Execute com um JDK configurado; os botões mostram apenas uma ação de exemplo.</p><div class="lab-actions"><button class="button button-secondary" data-action="copy-code">${icon('copy')} Copiar</button><button class="button button-primary" data-action="download-code">${icon('download')} Baixar .java</button></div></section><section class="lab-panel"><h2>Prévia do arquivo</h2><label class="lab-code-label" for="labCode">Edite o código gerado antes de copiar ou baixar</label><textarea id="labCode" class="lab-code-editor" spellcheck="false" aria-label="Código Java editável">${esc(labCodeOverride??java)}</textarea><p class="panel-note">A prévia acima acompanha os componentes. Alterações feitas diretamente no código serão testadas ao executar o arquivo no computador.</p></section></div>`;if(typeof applyLanguage==='function')applyLanguage()}
app.addEventListener('click',async e=>{const b=e.target.closest('button,[data-select]');if(!b)return;if(b.dataset.track){track=TRACKS.find(t=>t.id===b.dataset.track);screen='track';render();window.scrollTo(0,0);return}if(b.dataset.topic!==undefined){startLesson(Number(b.dataset.topic));return}if(b.dataset.choice!==undefined&&!answered){selected=Number(b.dataset.choice);renderLesson();return}if(b.dataset.add){addComponent(b.dataset.add);return}if(b.dataset.template){loadTemplate(b.dataset.template);return}if(b.dataset.select!==undefined){lab.selected=Number(b.dataset.select);renderLab();return}if(b.dataset.move){labCodeOverride=null;let i=lab.components.findIndex(x=>x.id===Number(b.dataset.move)),j=i+Number(b.dataset.dir);if(i>=0&&j>=0&&j<lab.components.length){[lab.components[i],lab.components[j]]=[lab.components[j],lab.components[i]];renderLab()}return}if(b.dataset.previewClick){toast('Prévia visual. A ação real é programada no arquivo Java.');return}
 if(typeof handleReviewClick==='function'&&handleReviewClick(b))return;switch(b.dataset.action){case 'back-home':navigate('home');break;case 'back-track':screen='track';render();window.scrollTo(0,0);break;case 'check':{let v=getQuestion(track,lesson.topic,lesson.q);if(v.kind==='choice'&&selected===null)return;if(v.kind==='code')codeAnswer=$('#exerciseEditor').value;answered=true;if(v.kind==='choice'&&typeof trackAnswer==='function')trackAnswer(v,selected);else if(v.kind==='choice'&&selected===v.correct)done(v.id);renderLesson();break}case 'hint':{let t=track.topics[lesson.topic];toast(`Pista: ${t[7]}. Procure usar ${t[8]}.`);break}case 'self-correct':done(getQuestion(track,lesson.topic,lesson.q).id);b.closest('.feedback')?.querySelectorAll('[data-action="self-correct"],[data-action="self-review"]').forEach(el=>el.disabled=true);toast('Prática marcada como compreendida.');break;case 'self-review':if(typeof trackSelfReview==='function')trackSelfReview(getQuestion(track,lesson.topic,lesson.q));b.closest('.feedback')?.querySelectorAll('[data-action="self-correct"],[data-action="self-review"]').forEach(el=>el.disabled=true);toast('Tudo bem. Volte a esta prática quando quiser.');break;case 'retry':answered=false;renderLesson();break;case 'next':lesson.q++;selected=null;answered=false;codeAnswer='';renderLesson();window.scrollTo(0,0);break;case 'restart':startLesson(lesson.topic);break;case 'next-topic':startLesson(lesson.topic+1);break;case 'remove':labCodeOverride=null;lab.components=lab.components.filter(x=>x.id!==lab.selected);lab.selected=null;renderLab();break;case 'copy-code':try{await navigator.clipboard.writeText(labCodeOverride??generatedJava());toast('Código copiado.')}catch{toast('Use Baixar .java para salvar o código.')}break;case 'download-code':downloadCode();toast('Arquivo MinhaTela.java baixado.');break;}}
);
